(function(){const c=$("#mesh"),x=c.getContext("2d");let W,H,P=[];const gold=()=>getComputedStyle(document.documentElement).getPropertyValue("--gold").trim()||"#e3b45c",cy=()=>getComputedStyle(document.documentElement).getPropertyValue("--cyan").trim()||"#4fd8e8";
function rs(){W=c.width=c.offsetWidth;H=c.height=c.offsetHeight;P=Array.from({length:Math.min(70,W/14|0)},()=>({x:Math.random()*W,y:Math.random()*H,vx:(Math.random()-.5)*.4,vy:(Math.random()-.5)*.4}))}
function d(){x.clearRect(0,0,W,H);const g=gold(),b=cy();P.forEach((p,i)=>{if(!RM){p.x+=p.vx;p.y+=p.vy}if(p.x<0||p.x>W)p.vx*=-1;if(p.y<0||p.y>H)p.vy*=-1;x.fillStyle=g;x.globalAlpha=.7;x.beginPath();x.arc(p.x,p.y,1.8,0,7);x.fill();for(let j=i+1;j<P.length;j++){const q=P[j],dx=p.x-q.x,dy=p.y-q.y,m=dx*dx+dy*dy;if(m<17000){x.globalAlpha=(1-m/17000)*.28;x.strokeStyle=b;x.beginPath();x.moveTo(p.x,p.y);x.lineTo(q.x,q.y);x.stroke()}}});if(!RM)requestAnimationFrame(d)}
addEventListener("resize",rs);rs();d()})();
